public static int guarded(boolean _fail)
{
    int result = 0;
    try
    {
        if (_fail)
        {
            throw Exception::Error;
        }
        result = 11;
    }
    catch (Exception::Error)
    {
        result = 7;
    }
    finally
    {
        result += 1;
    }
    return result;
}
